import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { toast } from "react-toastify";

const InfluencerApplyForReels = ({ onClose }) => {
  const navigate = useNavigate();
  
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    mobile: '',
    platform: '',
    profileUrl: ''
  });
  
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);
  
  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };
  
  const validateProfileUrl = (url, platform) => {
    if (platform === 'instagram') {
      // Instagram profile URL validation - allow with or without trailing slash
      const instagramRegex = /^https?:\/\/(www\.)?instagram\.com\/[a-zA-Z0-9._]+\/?(\?.*)?$/;
      return instagramRegex.test(url);
    } else if (platform === 'youtube') {
      // YouTube profile URL validation - handle various formats including with query parameters
      const youtubeRegex = /^https?:\/\/(www\.)?youtube\.com\/(@[a-zA-Z0-9._-]+|channel\/[a-zA-Z0-9._-]+|user\/[a-zA-Z0-9._-]+)\/?(\?.*)?$/;
      return youtubeRegex.test(url);
    }
    // For other platforms, allow any URL
    return true;
  };
  
  const handleSubmit = async (e) => {
    e.preventDefault();
    
    // Validate form
    if (!formData.firstName) {
      setError('First name is required');
      return;
    }
    
    if (!formData.lastName) {
      setError('Last name is required');
      return;
    }
    
    if (!formData.email) {
      setError('Email is required');
      return;
    }
    
    if (!formData.mobile) {
      setError('Mobile number is required');
      return;
    }
    
    if (!formData.platform) {
      setError('Please select a social media platform');
      return;
    }
    
    if (!formData.profileUrl) {
      setError('Profile URL is required');
      return;
    }
    
    // Validate profile URL based on platform
    if (!validateProfileUrl(formData.profileUrl, formData.platform)) {
      if (formData.platform === 'instagram') {
        setError('Please enter a valid Instagram profile URL (e.g., https://instagram.com/username)');
      } else if (formData.platform === 'youtube') {
        setError('Please enter a valid YouTube profile URL (e.g., https://youtube.com/@username or https://youtube.com/channel/channel_id)');
      } else {
        setError('Please enter a valid profile URL');
      }
      return;
    }
    
    // Validate mobile number format (basic validation)
    const mobileRegex = /^[0-9]{10,12}$/;
    if (!mobileRegex.test(formData.mobile)) {
      setError('Please enter a valid mobile number (10-12 digits)');
      return;
    }
    
    setLoading(true);
    setError('');
    
    try {
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 1000));
      setSuccess(true);
      toast.success("Application submitted successfully! We'll contact you soon.");
      
      // Instead of redirecting to a standalone page, close the modal and show login
      // Wait 3 seconds then switch to login view within the same modal
      setTimeout(() => {
        if (onClose) {
          // If we have an onClose function, call it to close the modal
          onClose();
          // Then open the login modal
          window.dispatchEvent(new CustomEvent('openLoginModal', { detail: 'influencer-login' }));
        } else {
          // If no onClose function, we're likely on a standalone page, so redirect
          navigate("/studio?message=pending_approval");
        }
      }, 3000);
    } catch (err) {
      console.error('Application error:', err);
      setError('Application failed. Please try again.');
    } finally {
      setLoading(false);
    }
  };
  
  return (
    <div className="container-fluid">
      <div className="row justify-content-center">
        <div className="col-12">
          {error && (
            <div className="alert alert-danger alert-dismissible fade show" role="alert">
              {error}
              <button 
                type="button" 
                className="btn-close" 
                data-bs-dismiss="alert" 
                aria-label="Close"
                onClick={() => setError("")}
              ></button>
            </div>
          )}
          
          {success && (
            <div className="alert alert-success alert-dismissible fade show" role="alert">
              Application successful! Redirecting to login page...
              <button 
                type="button" 
                className="btn-close" 
                data-bs-dismiss="alert" 
                aria-label="Close"
                onClick={() => setSuccess(false)}
              ></button>
            </div>
          )}
          
          <form onSubmit={handleSubmit} className="mt-3">
            <div className="mb-3">
              <label htmlFor="firstName" className="form-label">
                <i className="fas fa-user me-2"></i>First Name *
              </label>
              <input
                type="text"
                className="form-control form-control-lg rounded"
                id="firstName"
                name="firstName"
                value={formData.firstName}
                onChange={handleChange}
                required
                placeholder="Enter your first name"
              />
            </div>
            
            <div className="mb-3">
              <label htmlFor="lastName" className="form-label">
                <i className="fas fa-user me-2"></i>Last Name *
              </label>
              <input
                type="text"
                className="form-control form-control-lg rounded"
                id="lastName"
                name="lastName"
                value={formData.lastName}
                onChange={handleChange}
                required
                placeholder="Enter your last name"
              />
            </div>
            
            <div className="mb-3">
              <label htmlFor="email" className="form-label">
                <i className="fas fa-envelope me-2"></i>Email Address *
              </label>
              <input
                type="email"
                className="form-control form-control-lg rounded"
                id="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
                required
                placeholder="Enter your email"
              />
            </div>
            
            <div className="mb-3">
              <label htmlFor="mobile" className="form-label">
                <i className="fas fa-mobile-alt me-2"></i>Mobile Number *
              </label>
              <input
                type="tel"
                className="form-control form-control-lg rounded"
                id="mobile"
                name="mobile"
                value={formData.mobile}
                onChange={handleChange}
                required
                placeholder="Enter your mobile number"
              />
            </div>
            
            <div className="mb-3">
              <label htmlFor="platform" className="form-label">
                <i className="fas fa-hashtag me-2"></i>Social Media Platform *
              </label>
              <select
                className="form-select form-select-lg rounded"
                id="platform"
                name="platform"
                value={formData.platform}
                onChange={handleChange}
                required
              >
                <option value="">Select a platform</option>
                <option value="youtube">YouTube</option>
                <option value="instagram">Instagram</option>
                <option value="tiktok">TikTok</option>
                <option value="twitter">Twitter</option>
                <option value="other">Other</option>
              </select>
            </div>
            
            <div className="mb-3">
              <label htmlFor="profileUrl" className="form-label">
                <i className="fas fa-link me-2"></i>Profile URL *
              </label>
              <input
                type="text"
                className="form-control form-control-lg rounded"
                id="profileUrl"
                name="profileUrl"
                value={formData.profileUrl}
                onChange={handleChange}
                required
                placeholder="Enter your profile URL"
              />
              {formData.platform === 'instagram' && (
                <div className="form-text">Example: https://instagram.com/username</div>
              )}
              {formData.platform === 'youtube' && (
                <div className="form-text">Example: https://youtube.com/@username or https://youtube.com/channel/channel_id</div>
              )}
            </div>
            
            <div className="d-flex justify-content-between">
              <button
                type="button"
                className="btn btn-outline-secondary"
                onClick={onClose}
                disabled={loading}
              >
                Cancel
              </button>
              <button
                className="btn btn-primary d-flex align-items-center justify-content-center gap-1 fw-medium"
                type="submit"
                disabled={loading}
              >
                {loading ? (
                  <>
                    <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                    Submitting...
                  </>
                ) : (
                  <>
                    <i className="fas fa-paper-plane me-2"></i>Submit Application
                  </>
                )}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default InfluencerApplyForReels;
